using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
public static class ImporterTests {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 public static void Run(){var p=new YapiProfile{Name="test",Server="http://localhost:3000",SelectedKeys=new List<string>{"POST /api/submit"}};p.SetToken("test-only-secret");string json=JavaScanner.Serializer().Serialize(p);Check(!json.Contains("test-only-secret"),"Plaintext token leaked");var restored=JavaScanner.Serializer().Deserialize<YapiProfile>(json);Check(restored.Token()=="test-only-secret"&&restored.SelectedKeys.Count==1,"Encrypted profile round trip");
 string root=Path.Combine(Path.GetTempPath(),"mytool-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
 try{File.WriteAllText(Path.Combine(root,"DemoController.java"),"package demo; @RestController @RequestMapping(\"/api\") @Api(tags=\"Demo\") public class DemoController { @PostMapping(\"/submit\") @ApiOperation(\"Submit\") public Wrap<Input> submit(@RequestBody Input input){return null;} @GetMapping(\"/find\") public String find(@RequestParam(value=\"id\",required=false) Long id){return null;} @PostMapping(\"/file\") public String upload(@RequestParam(\"file\") MultipartFile file){return null;} @RequestMapping(\"/any\") public String any(){return null;} }");File.WriteAllText(Path.Combine(root,"Input.java"),"package demo; public class Input { @ApiModelProperty(value=\"Name\",required=true) private String name; @JsonSerialize(using=ToStringSerializer.class) private Long number; private static final String IGNORE=\"x\"; }");File.WriteAllText(Path.Combine(root,"Wrap.java"),"package demo; public class Wrap<T>{private T result;}");var entries=new JavaScanner(root).Scan(root);Check(entries.Count==4,"Controller count");var submit=entries.First(x=>x.Path=="/api/submit");Check(submit.Method=="POST"&&submit.Warning.Length==0,"Mapping parse");var schema=JavaScanner.Serializer().DeserializeObject((string)submit.Payload["req_body_other"]) as Dictionary<string,object>;var props=(Dictionary<string,object>)schema["properties"];Check(props.ContainsKey("name")&&!props.ContainsKey("IGNORE")&&((Dictionary<string,object>)props["number"])["type"].ToString()=="string","DTO fields");Check(((string)submit.Payload["res_body"]).Contains("Name"),"Generic result expansion");Check(entries.First(x=>x.Path=="/api/any").Selected==false,"Unspecified HTTP method must be flagged");Check(((List<object>)entries.First(x=>x.Path=="/api/file").Payload["req_body_form"]).Count==1,"Multipart upload");
 }finally{if(Directory.Exists(root))Directory.Delete(root,true);}
 var pane=new YapiPane();Check(pane.View.FindName("QuickUpload")!=null,"History quick upload UI");File.AppendAllText("test-results.txt",Environment.NewLine+"PASS: encrypted profile serialization, controller annotations, DTO schema, generics, multipart and history UI.");
 }
}
